734	## 模式 9：已读管理的 BitSet 编码（Read History with BitSet）
735	
736	### 设计意图
737	
738	需要记住每个场景中哪些句子已经读过。内存和存储开销要小（不能每个句子存一个 bool 字段）。
739	
740	### 核心实现
741	
742	```typescript
743	export class ReadHistoryManager {
744	  // Map<场景名, BitSet>
745	  private history: Map<string, Uint8Array> = new Map();
746	
747	  public checkIsRead() {
748	    const scenarioName = this.sceneManager.sceneData.currentScene.sceneName;
749	    const index = this.sceneManager.sceneData.currentSentenceId;
750	
751	    let isRead = false;
752	    if (this.history.has(scenarioName)) {
753	      const bitset = this.history.get(scenarioName)!;
754	      // bit 操作：index / 8 找字节，index % 8 找位
755	      isRead = (bitset[index >> 3] & (1 << (index & 7))) !== 0;
756	    }
757	
758	    // 更新 stage state（用于 TextBox 渲染已读灰色文本）
759	    webgalStore.dispatch(setStage({ key: 'isRead', value: isRead }));
760	
761	    if (!isRead) {
762	      this.addReadHistory();  // 标记为已读
763	    }
764	  }
765	
766	  private addReadHistory() {
767	    const scenarioName = ...;
768	    const index = ...;
769	
770	    // 首次为该场景创建 BitSet
771	    if (!this.history.has(scenarioName)) {
772	      const length = this.sceneManager.sceneData.currentScene.sentenceList.length;
773	      this.history.set(scenarioName, new Uint8Array(Math.ceil(length / 8)));
774	    }
775	
776	    let bitset = this.history.get(scenarioName)!;
777	
778	    // 处理剧本更新后 index 溢出的情况
779	    if ((index >> 3) >= bitset.length) {
780	      const newBitset = new Uint8Array(Math.ceil(newLength / 8));
781	      newBitset.set(bitset);  // 复制旧数据
782	      bitset = newBitset;
783	    }
784	
785	    bitset[index >> 3] |= (1 << (index & 7));  // 置位
786	    this.saveReadHistory(scenarioName);  // 持久化（base64 编码）
787	  }
788	}
789	```
790	
791	### 持久化编码
792	
793	```typescript
794	// 保存：Uint8Array → base64 → userData.readHistory[sceneName]
795	const base64 = Buffer.from(bitset).toString('base64');
796	webgalStore.dispatch(setReadHistory({ key: scenarioName, value: base64 }));
797	
798	// 加载：base64 → Uint8Array → history Map
799	const uint8 = Uint8Array.from(Buffer.from(value, 'base64'));
800	this.history.set(key, uint8);
801	```
802	
803	### 溢出处理（防御性）
804	
805	游戏更新后场景可能增加新的句子行，旧 BitSet 的容量可能不够。`addReadHistory` 中的 `newBitset` 扩展逻辑处理了这种情况。
806	
807	### Ring-rs 适配建议
808	
809	```rust
810	use bitvec::prelude::*;
811	
812	pub struct ReadHistory {
813	    // 场景名 → BitVec
814	    records: BTreeMap<String, BitVec>,
815	}
816	
817	impl ReadHistory {
818	    pub fn is_read(&self, scene: &str, line_index: usize) -> bool {
819	        self.records
820	            .get(scene)
821	            .and_then(|bits| bits.get(line_index))
822	            .map(|b| *b)
823	            .unwrap_or(false)
824	    }
825	
826	    pub fn mark_read(&mut self, scene: &str, total_lines: usize, line_index: usize) {
827	        let bits = self.records
828	            .entry(scene.to_string())
829	            .or_insert_with(|| bitvec![0; total_lines]);
830	        // 溢出扩展
831	        if line_index >= bits.len() {
832	            bits.resize(total_lines, false);
833	        }
834	        bits.set(line_index, true);
835	    }
836	}
837	```
