/// 游戏 iframe 通过 fetch `/__game_complete?result=xxx` 写入，
/// `MinigameOverlay` 轮询读取。
pub static GAME_COMPLETE_RESULT: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);

